INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('brief','brief','Brief universal',0,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('brief_v1','brief',1,'{"title":"Brief universal","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Contextul solicitării"}]},{"type":"paragraph","content":[{"type":"text","text":"Acest brief consemnează informațiile furnizate de beneficiar pentru definirea proiectului. El reprezintă baza analizei și a ofertei ulterioare; prețul, calendarul și obligațiile de livrare se confirmă în documentele comerciale aprobate."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitatea și publicul vizat: {{business_context}}. Obiectivele urmărite și rezultatele considerate utile: {{objectives}}. Serviciile și produsele analizate: {{scope}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Cerințe și priorități"}]},{"type":"paragraph","content":[{"type":"text","text":"Funcționalitățile, paginile, platformele sau procesele vizate sunt: {{requirements}}. Cerințele obligatorii se disting de opțiunile care pot fi implementate ulterior. Livrabilele așteptate: {{deliverables}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Pentru serviciile selectate, detaliile tehnice și limitele propuse sunt consemnate în secțiunile de serviciu. Integrările cu terți depind de disponibilitatea API-urilor, de conturile autorizate și de condițiile furnizorilor."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Materiale, acces și responsabilități"}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul indică materialele disponibile, proveniența și drepturile de utilizare: {{materials}}. Preferințe vizuale, ton și exemple relevante: {{preferences}}. Accesurile necesare se acordă individual prin mecanisme securizate; parolele și tokenurile nu se înscriu în brief."}]},{"type":"paragraph","content":[{"type":"text","text":"Persoanele responsabile de conținut și aprobări: {{contacts}}. Dependențele și restricțiile cunoscute: {{dependencies}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Buget și organizare"}]},{"type":"paragraph","content":[{"type":"text","text":"Bugetul orientativ și eventualele costuri externe acceptabile: {{budget}}. Data dorită și constrângerile de calendar: {{schedule}}. Aceste valori sunt informații de planificare până la confirmarea ofertei."}]},{"type":"paragraph","content":[{"type":"text","text":"Informațiile lipsă și întrebările deschise: {{open_questions}}. Beneficiarul verifică exactitatea datelor, iar echipa AVYRON formulează recomandarea de ofertare fără a considera completarea brief-ului drept acceptare contractuală."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","objectives","deliverables"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('audit','audit','Audit și evaluare',0,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('audit_v1','audit',1,'{"title":"Audit și evaluare","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Obiect și limite"}]},{"type":"paragraph","content":[{"type":"text","text":"Evaluarea privește {{scope}}, în starea observată la {{date}}. Obiectivele evaluării sunt {{objectives}}. Suprafețele, conturile, mediile și intervalul analizat: {{audit_targets}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Sunt incluse numai verificările autorizate și descrise aici. Evaluarea nu constituie o garanție că toate defectele sau vulnerabilitățile au fost identificate. Zonele inaccesibile și limitările de acces sunt consemnate explicit: {{limitations}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Metodologie"}]},{"type":"paragraph","content":[{"type":"text","text":"Metodele și instrumentele utilizate: {{methodology}}. Pentru fiecare constatare se păstrează sursa, momentul observației, mediul, pașii de reproducere și impactul demonstrat. Standardele ori criteriile aplicate sunt identificate prin versiune, când este relevant."}]},{"type":"paragraph","content":[{"type":"text","text":"Datele reale sunt folosite numai în limitele autorizării. Testele care pot afecta disponibilitatea, plățile sau datele necesită mandat distinct. Dovezile sunt minimizate și nu includ secrete."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Constatări și severitate"}]},{"type":"paragraph","content":[{"type":"text","text":"Situația observată: {{findings}}. Dovezile verificabile și referințele securizate: {{evidence}}. Severitatea și justificarea impactului: {{severity}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Fiecare rezultat este clasificat ca fapt confirmat, suspiciune de investigat sau verificare neexecutată. Un indicator de performanță, un scor automat ori o verificare punctuală nu înlocuiește evaluarea funcțională și contextuală."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Recomandări și urmărire"}]},{"type":"paragraph","content":[{"type":"text","text":"Măsurile propuse, în ordinea priorităților: {{recommendations}}. Responsabilii și dependențele: {{dependencies}}. Criteriile de reverificare: {{acceptance}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Raportul descrie starea la data auditului. Confirmarea remedierii presupune repetarea verificării relevante și înregistrarea rezultatului, mediului și versiunii evaluate. Costurile și termenele de implementare se aprobă separat."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","methodology","findings","evidence","recommendations"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('offer','offer','Ofertă comercială și deviz',0,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('offer_v1','offer',1,'{"title":"Ofertă comercială și deviz","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Context și propunere"}]},{"type":"paragraph","content":[{"type":"text","text":"AVYRON propune beneficiarului {{beneficiary.legal_name}} soluția descrisă în această ofertă pentru {{scope}}. Obiectivele urmărite: {{objectives}}. Varianta comercială și relația avută în vedere: {{offer_variant}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Soluția propusă și beneficiile urmărite: {{solution}}. Beneficiile reprezintă obiective de lucru; rezultatele dependente de piață, algoritmi, furnizori ori deciziile beneficiarului nu sunt garantate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Servicii, produse și livrabile"}]},{"type":"paragraph","content":[{"type":"text","text":"Serviciile și produsele ofertate sunt individualizate în deviz prin identificator, SKU unde există, cantitate, monedă și recurență. Livrabilele și limitele fiecărui element: {{deliverables}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Opțiuni incluse: {{inclusions}}. Opțiuni excluse și servicii ale terților: {{exclusions}}. Costurile media pentru Ads, licențele externe și taxele furnizorilor sunt separate de onorariul AVYRON și se includ numai dacă sunt înscrise expres."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Calendar și dependențe"}]},{"type":"paragraph","content":[{"type":"text","text":"Calendarul estimativ și etapele propuse: {{schedule}}. Acesta depinde de materialele, accesurile și aprobările indicate: {{dependencies}}. Orice modificare de scop se evaluează și se confirmă înainte de executare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Prețuri și condiții comerciale"}]},{"type":"paragraph","content":[{"type":"text","text":"Devizul păstrează prețul de catalog și prețul ofertat. Reducerile sau majorările se aplică exclusiv prezentei oferte și sunt motivate individual. Regimul fiscal aplicabil: {{tax_regime}}. Valorile recurente se disting de cele unice și de bugetele externe."}]},{"type":"paragraph","content":[{"type":"text","text":"Condițiile de plată, scadențele și eventualul avans: {{payment_terms}}. Durata serviciilor recurente: {{duration}}. Oferta este valabilă până la {{valid_until}}. Nicio taxă ori durată necompletată nu se consideră acceptată implicit."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Acceptare și pașii următori"}]},{"type":"paragraph","content":[{"type":"text","text":"Acceptarea se exprimă de reprezentanții autorizați pentru versiunea și pachetul selectate, prin {{acceptance_method}}. Condițiile de acceptare și eventualele documente ulterioare: {{acceptance}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Date de contact AVYRON: {{provider.contact_email}}. Reprezentanți și semnături, dacă sunt necesare: {{signatories}}. Prezenta ofertă nu autorizează debitarea automată a conturilor și nu înlocuiește condițiile contractuale care trebuie convenite separat."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","objectives","deliverables","schedule","payment_terms","valid_until","exclusions"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('framework','framework','Contract-cadru',1,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('framework_v1','framework',1,'{"title":"Contract-cadru","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Părțile și natura relației"}]},{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}, identificată prin {{provider.tax_id}}, cu sediul în {{provider.address}}, și {{beneficiary.legal_name}}, forma {{beneficiary.entity_type}}, cu sediul/adresa în {{beneficiary.address}}, convin prezentul contract prin reprezentanții {{signatories}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Relația juridică avută în vedere este {{relationship_type}}. Pentru parteneriate, colaborare independentă, subcontractare ori alte raporturi, dispozițiile specifice se verifică și se adaptează înainte de aprobare; titulatura documentului nu stabilește singură natura juridică."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Obiectul și documentele aplicabile"}]},{"type":"paragraph","content":[{"type":"text","text":"Obiectul convenit este {{scope}}. Livrabilele, limitele, etapele și criteriile măsurabile sunt stabilite în anexele acceptate: {{deliverables}}. În caz de neconcordanță, ordinea de prioritate convenită este {{document_priority}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Orice extindere de scop, tarif sau calendar se confirmă de persoanele autorizate înainte de executare. Solicitările și discuțiile tehnice nu modifică singure contractul."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Executarea și obligațiile părților"}]},{"type":"paragraph","content":[{"type":"text","text":"AVYRON execută activitățile convenite cu diligență profesională, documentează livrarea și comunică impedimentele cunoscute. Beneficiarul furnizează informații corecte, materiale utilizabile legal, accesuri limitate și aprobări prin responsabilii desemnați."}]},{"type":"paragraph","content":[{"type":"text","text":"Calendarul și dependențele sunt {{schedule}} și {{dependencies}}. Întârzierile determinate de neîndeplinirea unei dependențe se analizează și se reflectă într-un calendar actualizat confirmat de părți."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Preț, facturare și plată"}]},{"type":"paragraph","content":[{"type":"text","text":"Prețurile și moneda rezultă din anexele și devizele acceptate. Condițiile de plată sunt {{payment_terms}}, iar regimul fiscal confirmat este {{tax_regime}}. Costurile terților și bugetele media se suportă numai potrivit acordului expres."}]},{"type":"paragraph","content":[{"type":"text","text":"Recurențele, ajustările și condițiile de suspendare pentru neplată sunt {{recurring_terms}}. Nicio penalitate, reînnoire ori autorizare de debitare nu rezultă dintr-un câmp necompletat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 5. Livrare și acceptanță"}]},{"type":"paragraph","content":[{"type":"text","text":"Livrarea se notifică prin canalul convenit și este însoțită de informațiile necesare verificării. Procedura, criteriile și termenul de verificare sunt {{acceptance}}. Observațiile trebuie să indice neconformitățile raportate la scopul acceptat."}]},{"type":"paragraph","content":[{"type":"text","text":"Remedierea defectelor din scop se distinge de funcționalitățile noi. Acceptarea tacită, dacă este dorită, necesită o clauză expresă verificată juridic; simpla transmitere a fișierelor nu o instituie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 6. Proprietate intelectuală și servicii externe"}]},{"type":"paragraph","content":[{"type":"text","text":"Drepturile transferate sau licențiate, momentul producerii efectelor și excluderile sunt {{ip_terms}}. Componentele preexistente, instrumentele AVYRON și operele terților păstrează regimul de licență aplicabil."}]},{"type":"paragraph","content":[{"type":"text","text":"Accesul la un produs, abonament sau fișier nu transferă implicit codul-sursă ori drepturi exclusive. Beneficiarul răspunde pentru drepturile materialelor furnizate. Condițiile platformelor externe se aplică separat și nu pot fi garantate de AVYRON."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 7. Confidențialitate și date"}]},{"type":"paragraph","content":[{"type":"text","text":"Părțile limitează accesul la informațiile confidențiale la persoanele care au nevoie de ele pentru executare și aplică măsuri adecvate de protecție. Excepțiile, durata și obligațiile speciale sunt {{confidentiality_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Rolurile privind datele personale se stabilesc potrivit operațiunilor efective. Dacă este necesară prelucrarea în numele beneficiarului, părțile aprobă un acord distinct cu instrucțiunile și anexele relevante; acesta nu se presupune încheiat automat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 8. Răspundere, încetare și litigii"}]},{"type":"paragraph","content":[{"type":"text","text":"Regimul răspunderii și limitele negociate sunt {{liability_terms}}, cu respectarea dispozițiilor imperative aplicabile. Evenimentele neimputabile și procedura de notificare sunt {{force_majeure_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Durata, denunțarea, rezilierea, efectele încetării și predarea sunt {{termination_terms}}. Soluționarea disputelor și legea aplicabilă sunt {{governing_terms}}. Modificările se consemnează în scris de reprezentanții autorizați."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","deliverables","schedule","payment_terms","ip_terms","liability_terms","termination_terms","governing_terms","relationship_type"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('annex','annex','Anexă de servicii',1,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('annex_v1','annex',1,'{"title":"Anexă de servicii","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Legătura cu acordul principal"}]},{"type":"paragraph","content":[{"type":"text","text":"Prezenta anexă aparține acordului {{contract_reference}} și descrie {{scope}} pentru {{beneficiary.legal_name}}. Documentul identifică proiectele și instanțele de servicii cărora li se aplică; nu extinde acordul asupra altor beneficiari."}]},{"type":"paragraph","content":[{"type":"text","text":"Dacă sunt incluse mai multe servicii, limitele, livrabilele și costurile se individualizează pentru fiecare. Ordinea de prioritate între documente rămâne cea convenită în acordul principal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Livrabile și limite"}]},{"type":"paragraph","content":[{"type":"text","text":"Livrabilele contractate și formatele de predare sunt {{deliverables}}. Funcționalitățile, cantitățile, paginile, platformele, integrările și intervențiile incluse sunt {{requirements}}. Excluderile explicite sunt {{exclusions}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Lucrările suplimentare și reviziile care depășesc aceste limite necesită confirmarea impactului asupra costurilor și calendarului. Bugetele media, licențele, domeniile și taxele terților nu se confundă cu onorariul de implementare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Organizare și dependențe"}]},{"type":"paragraph","content":[{"type":"text","text":"Calendarul și punctele de aprobare sunt {{schedule}}. Materialele, accesurile și deciziile datorate de fiecare parte sunt {{dependencies}}. Responsabilii operaționali și canalele de comunicare: {{contacts}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Dependențele externe și condițiile tehnice de funcționare sunt {{technical_conditions}}. O integrare indisponibilă nu este prezentată ca activă; alternativele se aprobă înainte de utilizare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Costuri și acceptanță"}]},{"type":"paragraph","content":[{"type":"text","text":"Prețurile, moneda, regimul fiscal și recurențele sunt cele individualizate în devizul anexei și în {{payment_terms}}. Criteriile de acceptare, probele necesare și procedura de remediere sunt {{acceptance}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Drepturile asupra livrabilelor urmează {{ip_terms}}, în limitele acordului principal și ale licențelor terților. Anexa produce efecte numai pentru versiunea aprobată de reprezentanții {{signatories}}."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","contract_reference","deliverables","acceptance","schedule","payment_terms"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('access','access','Acord de acces și administrare',1,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('access_v1','access',1,'{"title":"Acord de acces și administrare","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Mandatul acordat"}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul autorizează persoanele desemnate de {{provider.legal_name}} să efectueze operațiunile {{access_scope}} asupra platformelor {{platforms}}, exclusiv pentru {{scope}}. Identificatorii conturilor și proprietarii lor sunt {{account_references}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Autorizarea este limitată la resursele, acțiunile și durata înscrise. Ea nu conferă dreptul de a transfera proprietatea, a modifica beneficiarii plăților, a accepta costuri sau a șterge definitiv date fără o aprobare distinctă."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Acordarea și protejarea accesului"}]},{"type":"paragraph","content":[{"type":"text","text":"Accesul se acordă prin utilizatori nominali, roluri delegate ori mecanisme OAuth/API cu privilegii minime. Parolele, codurile MFA, cheile private și tokenurile nu se înscriu în document și nu se trimit în canale nesecurizate."}]},{"type":"paragraph","content":[{"type":"text","text":"Responsabilii beneficiarului și ai prestatorului sunt {{contacts}}. Se păstrează evidența acțiunilor relevante și se evită conturile comune atunci când platforma permite conturi individuale."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Operațiuni și responsabilități"}]},{"type":"paragraph","content":[{"type":"text","text":"Publicarea, reclamele, modificările DNS, plățile și schimbările cu impact semnificativ necesită aprobările {{approval_rules}}. Prestatorul comunică erorile și incidentele cunoscute și nu prezintă o configurare drept operațiune finalizată fără dovadă."}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul menține dreptul asupra conturilor și verifică legalitatea materialelor și instrucțiunilor furnizate. Limitările furnizorilor, ferestrele de mesagerie și condițiile platformelor rămân aplicabile."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Durată și revocare"}]},{"type":"paragraph","content":[{"type":"text","text":"Mandatul este valabil pentru {{duration}}. Revocarea și procedura de predare sunt {{revocation}}. La încetare se retrag rolurile și tokenurile relevante, se predau informațiile necesare prin canale securizate și se consemnează rezultatul."}]},{"type":"paragraph","content":[{"type":"text","text":"Obligațiile de confidențialitate și conservare a evidențelor se aplică potrivit acordurilor relevante. Orice extindere de acces sau delegare ulterioară cere autorizare expresă."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","platforms","access_scope","duration","revocation"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('privacy','privacy','Confidențialitate și protecția datelor',1,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('privacy_v1','privacy',1,'{"title":"Confidențialitate și protecția datelor","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Scop și alegerea regimului"}]},{"type":"paragraph","content":[{"type":"text","text":"Părțile protejează informațiile schimbate pentru {{scope}}. Regimul selectat este {{privacy_mode}}. Secțiunea privind prelucrarea în numele unui operator se include numai dacă analiza operațiunilor reale o impune și dacă anexele obligatorii sunt completate."}]},{"type":"paragraph","content":[{"type":"text","text":"Sunt confidențiale informațiile identificate ca atare ori care, prin natura și contextul lor, trebuie protejate: {{confidentiality_terms}}. Nu sunt acoperite informațiile devenite publice legal, cunoscute anterior în mod legitim sau obținute independent fără încălcarea unei obligații."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Utilizare și divulgare"}]},{"type":"paragraph","content":[{"type":"text","text":"Informațiile sunt utilizate numai pentru scopul convenit și comunicate persoanelor autorizate care au nevoie de ele și au obligații corespunzătoare de confidențialitate. Măsurile de protecție și canalele permise sunt {{security_measures}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Divulgarea impusă legal se limitează la ceea ce este necesar și este notificată celeilalte părți când legea permite. Durata obligației și procedura de returnare sau ștergere sunt {{duration}} și {{return_deletion}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Roluri și instrucțiuni privind datele"}]},{"type":"paragraph","content":[{"type":"text","text":"Rolurile părților și temeiul relației se stabilesc în {{data_roles}}. Pentru o relație operator–persoană împuternicită, obiectul, durata, natura și scopul prelucrării, tipurile de date și categoriile de persoane vizate se descriu în anexa {{processing_annex}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Persoana împuternicită prelucrează datele numai pe baza instrucțiunilor documentate, asigură confidențialitatea persoanelor autorizate și aplică măsurile tehnice și organizatorice convenite. Instrucțiunile considerate contrare normelor aplicabile sunt semnalate operatorului."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Cerințe condiționale pentru acordul de prelucrare"}]},{"type":"paragraph","content":[{"type":"text","text":"Dacă se activează regimul DPA, subîmputerniciții și condițiile autorizării lor, transferurile internaționale și garanțiile aplicabile sunt {{subprocessors_transfers}}. Asistența pentru cereri ale persoanelor vizate, incidente, evaluări și verificări se organizează potrivit {{dpa_assistance}}."}]},{"type":"paragraph","content":[{"type":"text","text":"La încetare, datele sunt returnate sau șterse conform opțiunii documentate și obligațiilor legale de păstrare. Dovezile de conformitate și condițiile auditului sunt {{audit_conditions}}. Această secțiune nu poate fi aprobată fără anexele și verificarea de specialitate necesare."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","confidentiality_terms","duration","privacy_mode"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('implementation','implementation','Plan de implementare',0,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('implementation_v1','implementation',1,'{"title":"Plan de implementare","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Obiectiv și perimetru"}]},{"type":"paragraph","content":[{"type":"text","text":"Planul organizează realizarea {{scope}} și urmărește {{objectives}}. Livrabilele asumate în documentele comerciale sunt {{deliverables}}. Planul nu introduce singur servicii ori costuri suplimentare."}]},{"type":"paragraph","content":[{"type":"text","text":"Versiunea de referință a cerințelor și documentelor aprobate: {{contract_reference}}. Elementele excluse: {{exclusions}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Etape și responsabilități"}]},{"type":"paragraph","content":[{"type":"text","text":"Etapele, rezultatul fiecăreia, responsabilii și termenele sunt {{schedule}}. Fiecare etapă are un rezultat verificabil și o condiție explicită de intrare și ieșire. Activitățile paralele sunt permise numai când dependențele o permit."}]},{"type":"paragraph","content":[{"type":"text","text":"Responsabilii pentru accesuri, conținut, implementare, testare și aprobare sunt {{contacts}}. Beneficiarul indică persoana care poate decide asupra modificărilor de scop."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Dependențe și gestionarea schimbărilor"}]},{"type":"paragraph","content":[{"type":"text","text":"Dependențele tehnice și comerciale sunt {{dependencies}}. Riscurile cunoscute și măsurile de reducere sunt {{risks}}. Lipsa unei autorizări sau indisponibilitatea unui furnizor este evidențiată ca blocaj, fără simularea finalizării."}]},{"type":"paragraph","content":[{"type":"text","text":"Schimbările se înregistrează cu motiv, impact, responsabil și aprobarea necesară. Calendarul se actualizează pentru versiunea nouă fără a rescrie istoricul deciziilor anterioare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Verificare și finalizare"}]},{"type":"paragraph","content":[{"type":"text","text":"Criteriile de finalizare și dovezile cerute sunt {{acceptance}}. Se verifică separat mediul local, preview și producția, precum și funcțiile dependente de furnizori externi."}]},{"type":"paragraph","content":[{"type":"text","text":"Predarea include documentația convenită, evidența limitărilor rămase și pașii de suport. Publicarea în producție, comunicarea externă și operațiunile financiare urmează propriile aprobări."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","deliverables","schedule","dependencies","acceptance"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('report','report','Raport universal',0,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('report_v1','report',1,'{"title":"Raport universal","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Perioadă și obiect"}]},{"type":"paragraph","content":[{"type":"text","text":"Raportul acoperă {{period}} pentru {{scope}} și se raportează la obiectivele {{objectives}}. Tipul de raport și sursele utilizate: {{report_type}} și {{data_sources}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Sunt separate activitățile executate, rezultatele observate și acțiunile propuse. Configurarea unui serviciu sau pregătirea unei operațiuni nu este prezentată drept livrare finală."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Activități și livrabile"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitățile efectuate și starea fiecăreia: {{activities}}. Livrabilele și versiunile la care se referă raportul: {{deliverables}}. Responsabilii și intervențiile beneficiarului: {{contacts}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Pentru campanii, costul media se distinge de onorariu; pentru mentenanță, monitorizarea se distinge de intervenția efectivă; pentru agenți AI, propunerile se disting de acțiunile aprobate și executate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Rezultate și dovezi"}]},{"type":"paragraph","content":[{"type":"text","text":"Indicatorii, metodologia de calcul și comparațiile relevante sunt {{metrics}}. Dovezile verificabile, mediul și momentul observației: {{evidence}}. Constatările și incidentele: {{findings}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Datele indisponibile nu sunt înlocuite cu estimări prezentate ca fapte. Scorurile automate, atribuirea conversiilor și măsurătorile punctuale se interpretează în limitele surselor și perioadei analizate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Recomandări și următorii pași"}]},{"type":"paragraph","content":[{"type":"text","text":"Prioritățile recomandate și justificarea lor sunt {{recommendations}}. Dependențele și aprobările necesare: {{dependencies}}. Activitățile rămase și calendarul propus: {{schedule}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Raportul este verificat înainte de publicare. Rezultatele sunt valabile în contextul descris și nu constituie o promisiune privind poziționări, vânzări, disponibilitate ori absența totală a incidentelor viitoare."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","period","activities","evidence","findings","recommendations"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('handover','handover','Proces-verbal de recepție și predare',1,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('handover_v1','handover',1,'{"title":"Proces-verbal de recepție și predare","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Obiectul predării"}]},{"type":"paragraph","content":[{"type":"text","text":"Părțile consemnează predarea {{scope}}, aferentă acordului {{contract_reference}}, pentru proiectele și serviciile asociate explicit documentului. Livrabilele, versiunile, mediile și formatele predate: {{deliverables}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Data predării și participanții sunt {{date}} și {{signatories}}. Documentul se referă exclusiv la elementele inventariate, fără a presupune acceptarea altor lucrări."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Verificări și rezultat"}]},{"type":"paragraph","content":[{"type":"text","text":"Verificările efectuate, criteriile aplicate și dovezile sunt {{evidence}}. Rezultatul recepției este {{acceptance}}. Se disting elementele acceptate, cele acceptate cu observații și cele pentru care recepția se amână."}]},{"type":"paragraph","content":[{"type":"text","text":"Observațiile și neconformitățile identificate: {{observations}}. Măsurile de remediere, responsabilii și termenele confirmate: {{remediation}}. Funcționalitățile suplimentare solicitate ulterior se tratează separat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Accesuri și documentație"}]},{"type":"paragraph","content":[{"type":"text","text":"Conturile, rolurile, domeniile, depozitele și documentația predate sunt inventariate prin referințe în {{access_inventory}}. Accesurile sunt transferate prin {{secure_channel}}, fără parole, tokenuri, coduri MFA sau chei private înscrise în acest proces-verbal."}]},{"type":"paragraph","content":[{"type":"text","text":"Drepturile de proprietate intelectuală și licențele rămân cele din documentele aprobate: {{ip_terms}}. Predarea accesului tehnic nu conferă automat drepturi suplimentare asupra produselor ori componentelor terților."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Efecte și suport ulterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Efectele recepției asupra plăților și începutului mentenanței sunt {{handover_effects}}. Serviciile de suport ulterioare se acordă potrivit {{support_reference}} și nu se presupun nelimitate."}]},{"type":"paragraph","content":[{"type":"text","text":"Fiecare parte verifică exactitatea inventarului și păstrează versiunea aprobată. Corecturile ulterioare se consemnează într-un document nou, fără suprascrierea prezentului proces-verbal."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","contract_reference","deliverables","evidence","acceptance","observations"]','review_required',0);
INSERT INTO document_templates(id,family,name,legal,created_at) VALUES ('sla','sla','Acord mentenanță / SLA',1,0);
INSERT INTO document_template_versions(id,template_id,version,payload_json,required_fields_json,review_status,created_at) VALUES ('sla_v1','sla',1,'{"title":"Acord mentenanță / SLA","header":"AVYRON · {{provider.legal_name}} · {{date}}","footer":"Document privat · {{beneficiary.legal_name}} · versiunea și numărul sunt înscrise la export","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prestator / emitent: {{provider.legal_name}}. Beneficiar / destinatar: {{beneficiary.legal_name}}. Data: {{date}}. Obiect: {{scope}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Serviciile acoperite"}]},{"type":"paragraph","content":[{"type":"text","text":"Acordul privește {{scope}} și resursele inventariate în {{coverage}}. Sunt incluse intervențiile, actualizările și monitorizarea descrise expres. Funcțiile noi, refacerile majore și resursele terților sunt excluse dacă nu sunt înscrise separat."}]},{"type":"paragraph","content":[{"type":"text","text":"Limitele de volum, timp ori număr de intervenții sunt {{service_limits}}. Nu există un nivel de disponibilitate sau suport permanent implicit."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Solicitări și niveluri de suport"}]},{"type":"paragraph","content":[{"type":"text","text":"Canalele, programul de suport, clasificarea incidentelor și țintele de răspuns/remediere sunt {{support_levels}}. Timpul de răspuns se distinge de timpul de soluționare. Persoanele autorizate să solicite intervenții: {{contacts}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Țintele se calculează conform metodei {{measurement_method}}, ținând cont de dependențe și de perioadele excluse convenite. Indisponibilitatea furnizorilor se raportează distinct."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Actualizări și schimbări"}]},{"type":"paragraph","content":[{"type":"text","text":"Actualizările se evaluează în raport cu compatibilitatea, securitatea și impactul. Ferestrele de mentenanță și aprobările sunt {{maintenance_windows}}. Schimbările cu risc semnificativ presupun o procedură de revenire documentată."}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul menține accesurile necesare și comunică modificările făcute de terți. O intervenție care depășește scopul se estimează și se aprobă separat înainte de executare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Backup și restaurare"}]},{"type":"paragraph","content":[{"type":"text","text":"Ce se salvează, frecvența, destinația privată, retenția și excluderile sunt {{backup_policy}}. Protecția bazei de date se distinge de copia fișierelor și de configurațiile furnizorilor."}]},{"type":"paragraph","content":[{"type":"text","text":"Procedura de restaurare, responsabilitățile, țintele confirmate și verificările periodice sunt {{restore_policy}}. Un backup nu este considerat verificat numai pentru că operațiunea de creare a răspuns fără eroare. Costurile și limitele de stocare sunt {{storage_terms}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 5. Durată, tarife și încetare"}]},{"type":"paragraph","content":[{"type":"text","text":"Durata este {{duration}}, tarifele și condițiile de plată sunt {{payment_terms}}, iar regimul fiscal este {{tax_regime}}. Reînnoirea și notificările sunt {{renewal_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Suspendarea, încetarea, exportul datelor și predarea accesurilor sunt {{termination_terms}}. Răspunderea și eventualele compensații de serviciu sunt {{liability_terms}}, în limitele normelor aplicabile și ale acordului principal."}]}]},"fields":{},"labels":{},"lines":[]}','["date","provider.legal_name","beneficiary.legal_name","scope","provider.tax_id","provider.address","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","coverage","support_levels","backup_policy","restore_policy","duration","payment_terms","renewal_terms"]','review_required',0);
